#!/usr/bin/env node
// Generates the database-schema reference from the latest Drizzle snapshot.
//
// Source: apps/api/src/db/migrations/meta/<latest>_snapshot.json — the JSON
// description Drizzle Kit writes alongside every migration. That is a better
// source than the schema TypeScript: it is already resolved (column types,
// defaults, constraints, foreign keys) and it is regenerated by the same tool
// that produces the SQL, so it cannot describe a schema the migrations do not
// produce.
//
// The snapshot is picked by the journal's last entry rather than by filename
// sort, so it follows the migration order Drizzle itself uses.
//
// Usage: node scripts/gen-db-schema.mjs
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const scriptDir = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(scriptDir, '../../..');
const META = join(repoRoot, 'apps/api/src/db/migrations/meta');
const OUT = join(scriptDir, '../src/content/docs/self-hosting/reference/db-schema.mdx');

/**
 * Grouping for the table list. A table not named here lands in "Other", which is
 * visible in the output rather than silently dropped.
 */
const GROUPS = [
  [
    'Accounts and users',
    ['users', 'sessions', 'email_tokens', 'accounts', 'brokerages', 'fee_schedules'],
  ],
  ['Trading', ['positions', 'fills']],
  ['Money', ['ledger_entries', 'expenses', 'exchange_rates', 'wallets', 'wallet_transactions']],
  [
    'Advisor',
    [
      'advisor_conversations',
      'advisor_messages',
      'advisor_summaries',
      'advisor_personas',
      'advisor_provider_keys',
      'advisor_turn_counters',
      'advisor_image_counters',
    ],
  ],
  ['Import', ['csv_import_staging', 'csv_import_counters']],
  ['Billing', ['billing_customers', 'subscriptions', 'usage_records', 'webhook_events']],
  [
    'Platform',
    [
      'symbols',
      'symbol_sync_state',
      'dashboard_layouts',
      'external_api_keys',
      'admin_audit_log',
      '_post_migrations_journal',
    ],
  ],
];

function latestSnapshot() {
  const journal = JSON.parse(readFileSync(join(META, '_journal.json'), 'utf8'));
  const entries = [...journal.entries].sort((a, b) => a.when - b.when);
  if (entries.length === 0) throw new Error('gen-db-schema: the migration journal is empty');
  // Walk BACK to the newest entry that actually has a snapshot. Not every
  // migration does: a data-only one (0021's dashboard row-unit rescale, 0028's
  // onboarding backfill) is hand-authored, changes no DDL, and Drizzle Kit — the
  // only thing that writes snapshots — was never involved. Such a migration
  // leaves the schema exactly as the previous snapshot describes it, so that
  // snapshot is the correct source; taking the last journal entry unconditionally
  // just crashed on a missing file the moment a data migration shipped last.
  for (let i = entries.length - 1; i >= 0; i--) {
    const file = join(META, `${String(entries[i].idx).padStart(4, '0')}_snapshot.json`);
    if (existsSync(file)) return { file, tag: entries[i].tag, count: entries.length };
  }
  throw new Error('gen-db-schema: no migration in the journal has a snapshot');
}

/**
 * Escape a value for a markdown table cell.
 *
 * Backslash FIRST, then the pipe — escaping the pipe first would leave the
 * backslash it introduced to be escaped again, turning `a|b` into `a\\|b` and
 * breaking the column. Newlines would break the row outright, so they collapse
 * to a space.
 */
function cell(value) {
  return String(value)
    .replace(/\\/g, '\\\\')
    .replace(/\|/g, '\\|')
    .replace(/\s+/g, ' ')
    .trim();
}

/** Render one column's type with its nullability and default. */
function columnRow(name, col) {
  const bits = [];
  if (col.primaryKey) bits.push('primary key');
  if (col.notNull && !col.primaryKey) bits.push('not null');
  if (col.default !== undefined && col.default !== null) {
    bits.push(`default \`${cell(col.default)}\``);
  }
  return `| \`${name}\` | \`${col.type}\` | ${bits.join(', ') || '—'} |`;
}

function foreignKeyLines(table) {
  const fks = Object.values(table.foreignKeys ?? {});
  return fks.map((fk) => {
    const from = (fk.columnsFrom ?? []).join(', ');
    const to = (fk.columnsTo ?? []).join(', ');
    const onDelete = fk.onDelete ? ` on delete ${fk.onDelete}` : '';
    return `- \`${from}\` → \`${fk.tableTo}.${to}\`${onDelete}`;
  });
}

const { file, tag, count } = latestSnapshot();
const snapshot = JSON.parse(readFileSync(file, 'utf8'));
const tables = Object.values(snapshot.tables);

if (tables.length < 20) {
  throw new Error(`gen-db-schema: only ${tables.length} tables in the snapshot — generator is stale`);
}

const byName = new Map(tables.map((t) => [t.name, t]));
const grouped = new Set(GROUPS.flatMap(([, names]) => names));
const other = tables.map((t) => t.name).filter((n) => !grouped.has(n)).sort();
const groups = other.length > 0 ? [...GROUPS, ['Other', other]] : GROUPS;

const out = [];
out.push('---');
out.push('title: Database schema');
out.push(
  'description: Every table Tradr creates, its columns, and how they reference each other — generated from the Drizzle migration snapshot.',
);
out.push('---');
out.push('');
out.push('{/* GENERATED FILE — do not edit.');
out.push(`    Source: apps/api/src/db/migrations/meta/ (latest snapshot) · Generator: apps/docs/scripts/gen-db-schema.mjs */}`);
out.push('');
out.push(`Tradr's schema is **${tables.length} tables**, created by **${count} migrations** that run`);
out.push('automatically when the api boots. This page is generated from the Drizzle snapshot');
out.push(`for the latest schema-changing migration (\`${tag}\`), so it describes the schema the migrations`);
out.push('actually produce.');
out.push('');
out.push('You do not need any of this to run Tradr. It is here for writing queries against');
out.push('your own data, and for reading the code.');
out.push('');
out.push(':::caution');
out.push('The schema is not a stable interface before 1.0. Migrations are forward-only and');
out.push('additive — see [Database & migrations](/self-hosting/explanation/migrations/) — but');
out.push('a query you write against these tables may need updating on any release.');
out.push(':::');
out.push('');

for (const [groupName, names] of groups) {
  const present = names.filter((n) => byName.has(n));
  if (present.length === 0) continue;
  out.push(`## ${groupName}`);
  out.push('');
  for (const name of present) {
    const table = byName.get(name);
    out.push(`### \`${name}\``);
    out.push('');
    out.push('| Column | Type | Notes |');
    out.push('| --- | --- | --- |');
    for (const [colName, col] of Object.entries(table.columns)) {
      out.push(columnRow(colName, col));
    }
    out.push('');
    const fks = foreignKeyLines(table);
    if (fks.length > 0) {
      out.push('**References**');
      out.push('');
      out.push(...fks);
      out.push('');
    }
  }
}

out.push('## Next steps');
out.push('');
out.push('- [Database & migrations](/self-hosting/explanation/migrations/) — how the schema changes.');
out.push('- [Back up and restore](/self-hosting/backup-restore/) — a `pg_dump` captures all of this.');
out.push('- [Architecture overview](/self-hosting/explanation/architecture/) — where the database sits.');
out.push('');

writeFileSync(OUT, out.join('\n'));
console.log(
  `gen-db-schema: wrote ${OUT} (${tables.length} tables from ${tag}, ${other.length} ungrouped).`,
);
